def merge_intervals(intervals):
    intervals = sorted((tuple(interval) for interval in intervals))
    if not intervals:
        return []

    merged = []
    start, end = intervals[0]

    for next_start, next_end in intervals[1:]:
        if next_start <= end:
            if next_end > end:
                end = next_end
        else:
            merged.append((start, end))
            start, end = next_start, next_end

    merged.append((start, end))
    return merged
